INSERT INTO audit_log (id, entity, entity_id, action, before, after, user_id)
SELECT gen_random_uuid()::text, 'variant', o.id, 'package', jsonb_build_object('pkgMm', NULL),
       jsonb_build_object('pkgMm', jsonb_build_array(o.l, o.w, o.h), 'reason', 'Delta Pro'), NULL
FROM old o JOIN upd u ON u.id = o.id;
